// Appearance and personal widgets stay on this device. No account or network access.
(()=>{
 const defaults={theme:'system',accent:'clay',frame:'modern',density:'comfortable',corners:'round',sidebar:'icons',widgets:['checklist','calendar','music']};
 const choices={theme:['system','light','dark'],accent:['clay','sage','sky','grape','rose'],frame:['modern','plain'],density:['comfortable','compact','spacious'],corners:['round','sharp'],sidebar:['icons','labels']};
 const names={actions:'Action Desk',checklist:'Checklist',calendar:'Calendar',music:'Music player',clock:'Clock'};let settings={...defaults,widgets:[...defaults.widgets]},tasks=[],events=[],playing=false;
 try{const saved=JSON.parse(localStorage.getItem('stupid-mail-customize')||'{}');for(const key in choices)if(choices[key].includes(saved[key]))settings[key]=saved[key];if(Array.isArray(saved.widgets))settings.widgets=[...new Set(saved.widgets.filter(k=>Object.hasOwn(names,k)))];const stored=JSON.parse(localStorage.getItem('stupid-mail-checklist')||'[]');if(Array.isArray(stored))tasks=stored.filter(t=>t&&typeof t.text==='string'&&typeof t.id==='string').slice(0,100).map(t=>({...t,text:t.text.slice(0,160),done:!!t.done}))}catch{}
 function persist(){try{localStorage.setItem('stupid-mail-customize',JSON.stringify(settings));$('#customize-status').textContent='Saved on this Mac.'}catch{$('#customize-status').textContent='Could not save settings on this device.'}}
 function taskSave(){try{localStorage.setItem('stupid-mail-checklist',JSON.stringify(tasks))}catch{toast('The checklist could not be saved on this device.')}}
 function apply(){const root=document.documentElement;for(const key in choices){root.dataset[key]=settings[key];$('#look-'+key).value=settings[key]}const accents={clay:'#D97757',sage:'#6F9161',sky:'#4F8CC9',grape:'#9270B5',rose:'#BC7183'};root.style.setProperty('--accent',accents[settings.accent]);root.style.setProperty('--accent-soft','color-mix(in srgb, var(--accent) 14%, transparent)');render();options()}
 function open(){if(document.querySelector('dialog[open]'))return;$('#customize-dialog').showModal()}
 $('#customize-open').onclick=open;
 for(const key in choices)$('#look-'+key).onchange=e=>{settings[key]=e.target.value;apply();persist()};
 function options(){$('#widget-options').innerHTML=Object.entries(names).map(([id,title])=>`<label class="widget-option"><input type="checkbox" data-widget="${id}" ${settings.widgets.includes(id)?'checked':''}>${title}</label>`).join('')}
 $('#widget-options').onchange=e=>{const id=e.target.dataset.widget;if(!Object.hasOwn(names,id))return;if(e.target.checked&&!settings.widgets.includes(id))settings.widgets.push(id);else settings.widgets=settings.widgets.filter(k=>k!==id);render();persist()};
 $('#look-reset').onclick=()=>{settings={...defaults,widgets:[...defaults.widgets]};apply();persist()};
 function content(id){
  if(id==='actions')return '<p class="widget-hint">Turn a conversation into a promise you can keep. Tasks link back to the original email.</p><button data-widget-action="actions">Open Action Desk →</button>';
  if(id==='checklist')return `<div class="widget-tasks">${tasks.map(t=>`<div class="widget-task"><label><input type="checkbox" data-task="${escape(t.id)}" ${t.done?'checked':''}><span class="${t.done?'completed':''}">${escape(t.text)}</span></label><button data-remove-task="${escape(t.id)}" aria-label="Remove ${escape(t.text)}">×</button></div>`).join('')||'<p class="widget-hint">A few small things for today.</p>'}</div><form id="widget-task-form"><input id="widget-task-input" placeholder="Add a little task…" aria-label="New checklist task" maxlength="160" required><button aria-label="Add task">＋</button></form>`;
  if(id==='calendar')return `<div class="widget-agenda">${events.slice(0,3).map(e=>`<div><strong>${escape(e.title)}</strong><small>${escape(new Date(e.start).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</small></div>`).join('')||'<p class="widget-hint">Room for good conversations.<br>Open Calendar to load your plans.</p>'}</div><button data-widget-action="calendar">Open calendar →</button>`;
  if(id==='music')return `<div class="music-orb ${playing?'playing':''}" aria-hidden="true">♫</div><p class="widget-hint">A softer soundtrack to your inbox.</p><button data-widget-action="music">${playing?'Pause music':'Play soft music'}</button><label class="widget-volume">Volume<input id="widget-music-volume" type="range" min="0" max="100" value="${Number($('#music-volume').value)||0}" aria-label="Music widget volume"></label>`;
  return '<div id="widget-clock-time"></div><div id="widget-clock-date" class="widget-hint"></div><p class="widget-hint">One thing at a time.</p>';
 }
 function render(){$('#widgets').innerHTML=settings.widgets.map((id,i)=>`<article class="widget-card" data-widget-card="${id}"><header><h3>${names[id]}</h3><div><button data-move-widget="${id}" data-direction="-1" aria-label="Move ${names[id]} earlier" ${i===0?'disabled':''}>←</button><button data-move-widget="${id}" data-direction="1" aria-label="Move ${names[id]} later" ${i===settings.widgets.length-1?'disabled':''}>→</button><button data-hide-widget="${id}" aria-label="Remove ${names[id]} widget">×</button></div></header>${content(id)}</article>`).join('')+`<button id="add-widgets">＋ Add widgets</button>`;$('#add-widgets').onclick=open;const taskForm=document.querySelector('#widget-task-form');if(taskForm)taskForm.onsubmit=e=>{e.preventDefault();const text=$('#widget-task-input').value.trim();if(!text)return;if(tasks.length>=100){toast('Your checklist has 100 tasks. Remove a few before adding more.');return}tasks.push({id:crypto.randomUUID(),text:text.slice(0,160),done:false});taskSave();render();$('#widget-task-input').focus()};tick()}
 $('#widgets').onclick=e=>{const hide=e.target.closest('[data-hide-widget]'),move=e.target.closest('[data-move-widget]'),remove=e.target.closest('[data-remove-task]'),action=e.target.closest('[data-widget-action]');if(hide){settings.widgets=settings.widgets.filter(id=>id!==hide.dataset.hideWidget);render();options();persist()}if(move){const from=settings.widgets.indexOf(move.dataset.moveWidget),to=from+Number(move.dataset.direction);if(from>=0&&to>=0&&to<settings.widgets.length){[settings.widgets[from],settings.widgets[to]]=[settings.widgets[to],settings.widgets[from]];render();persist()}}if(remove){tasks=tasks.filter(t=>t.id!==remove.dataset.removeTask);taskSave();render()}if(action){if(action.dataset.widgetAction==='actions')$('#open-actions').click();if(action.dataset.widgetAction==='calendar')$('#open-calendar').click();if(action.dataset.widgetAction==='music')$('#music-toggle').click()}};
 $('#widgets').onchange=e=>{if(e.target.dataset.task){const task=tasks.find(t=>t.id===e.target.dataset.task);if(task){task.done=e.target.checked;taskSave();render()}}};
 $('#widgets').oninput=e=>{if(e.target.id==='widget-music-volume'){$('#music-volume').value=e.target.value;$('#music-volume').oninput()}};
 function tick(){const clock=document.querySelector('#widget-clock-time');if(clock){clock.textContent=new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});$('#widget-clock-date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}}
 window.addEventListener('calendar-updated',e=>{events=e.detail;render()});
 window.addEventListener('music-updated',e=>{playing=e.detail.playing;const button=document.querySelector('[data-widget-action="music"]');if(button)button.textContent=playing?'Pause music':'Play soft music';const orb=document.querySelector('.music-orb');orb?.classList.toggle('playing',playing);const slider=document.querySelector('#widget-music-volume');if(slider)slider.value=String(e.detail.volume)});
 setInterval(tick,30000);apply();
})();
